const fig=(title,o)=>({t:'figure',title,dots:'',...o,hide:Object.keys(o.pts||{}).join('')});
const board=(title,lines)=>({t:'board',title,lines,box:true});
const bars=(title,labels,values)=>({t:'chart',kind:'bars',title,bars:labels.map((label,i)=>({label,value:values[i]}))});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>49){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
const flow=(title,labels,foot)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((text,i)=>{const x=i*10;Object.assign(pts,{['A'+i]:[x,0],['B'+i]:[x+8,0],['C'+i]:[x+8,3],['D'+i]:[x,3]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:i%4});notes.push({at:[x+4,1.5],text});if(i){pts['E'+i]=[x-2,1.5];pts['F'+i]=[x,1.5];segs.push({v:`E${i}F${i}`,arrows:1,col:1});}});notes.push({at:[(labels.length*10-2)/2,-2],text:foot});return fig(title,{pts,polys,segs,notes,view:[-1,labels.length*10-1,-4,6]});};
/* net: labelled boxes joined by arrows, from the lesson's own coordinates; each arrow carries a chevron pointing to its end */
const net=(title,boxes,arrows,notes,view)=>{const pts={},polys=[],segs=[];boxes.forEach(([k,x0,y0,x1,y1,label,col])=>{Object.assign(pts,{[k+'1']:[x0,y0],[k+'2']:[x1,y0],[k+'3']:[x1,y1],[k+'4']:[x0,y1]});polys.push({v:`${k}1${k}2${k}3${k}4`,col,label});});arrows.forEach(([x0,y0,x1,y1,col],i)=>{pts['a'+i]=[x0,y0];pts['b'+i]=[x1,y1];segs.push({v:`a${i}b${i}`,arrows:1,col});});return fig(title,{pts,polys,segs,notes:notes.map(([x,y,text,col])=>({at:[x,y],text,col})),view});};
const LEVELS=flow('Levels of ecological organization',['organism','population','community','ecosystem','biome'],'each level contains the levels before it');
const BIOMES={t:'plot',title:'Schematic climate map of biomes (approximate)',x:[-15,30],y:[0,450],areas:[{pts:[[-15,0],[-15,50],[0,120],[30,450],[30,0]],col:2}],points:[{x:-10,y:20,label:'tundra'},{x:-8,y:75,label:'boreal forest'},{x:8,y:45,label:'grassland'},{x:12,y:130,label:'temperate forest'},{x:24,y:12,label:'desert'},{x:24,y:110,label:'savanna'},{x:25,y:320,label:'tropical rainforest'}]};
const LAKE=fig('Lake zones in cross-section (schematic)',{pts:{A:[0,6],B:[36,6],C:[36,-7],D:[12,-7],E:[7,-3],F:[3,2],G:[5,0],H:[36,0]},polys:[{v:'ABCDEF',col:0}],segs:[{v:'GH',col:3,dash:true}],notes:[{at:[4.5,4.2],text:'littoral'},{at:[22,3.2],text:'limnetic: open, lit water'},{at:[22,-2.8],text:'profundal: below the light'},{at:[24,-6],text:'benthic: bottom'},{at:[31,0.9],text:'light limit',col:3}],view:[-2,40,-8,8]});
const ESTUARY={t:'plot',title:'Fictional estuary: x = km from river mouth; y = salinity (ppt)',x:[0,40],y:[0,40],paths:[{pts:[[0,0.5],[10,4],[20,14],[30,27],[40,34]]}],points:[{x:2,y:1,label:'river water'},{x:20,y:14,label:'brackish mix'},{x:38,y:34,label:'near seawater'}]};
const CARBON=net('Carbon cycle: boxes are reservoirs, arrows are flows',[['A',5,9,30,12.5,'atmosphere: CO2',0],['P',0,0,9,4,'producers',2],['C',12,0,25,4,'consumers, decomposers',2],['O',30,0,40,4,'ocean, sediments',3],['F',33,8.5,42,12,'fossil fuels',1]],[[3.5,9,3.5,4.2,2],[6.5,4,6.5,9,1],[9.2,2,11.8,2,2],[18.5,4,18.5,9,1],[29,9,34,4.2,3],[33,10.2,30.2,10.2,4]],[[0,6.6,'photosynthesis'],[11.5,6.6,'respiration'],[10.5,-0.9,'eaten'],[24.5,6.6,'respiration, decay'],[37.5,6.6,'gas exchange'],[31.6,13.3,'burning']],[-4,44,-2,14.5]);
const NITROGEN=net('Nitrogen cycle: bacteria drive most steps',[['N',12,10.5,29,14,'N2 gas in the air (about 78%)',0],['A',0,4.5,10,8,'NH4+ (ammonium)',2],['V',34,4.5,44,8,'NO3− (nitrate)',2],['O',13,-1,31,2.5,'organic N: plants, animals',3]],[[14,10.4,6,8.1,2],[10.2,6.2,33.8,6.2,2],[36,8.1,29,10.9,1],[4,4.4,12.8,1.5,2],[40,4.4,31.2,1.5,2],[15,2.7,9,4.4,1]],[[4,10.2,'fixation'],[22,7.3,'nitrification'],[39,10.6,'denitrification'],[3,0.3,'assimilation'],[41,1.2,'assimilation'],[22,4.3,'ammonification']],[-2,46,-2,15]);
const PHOS=net('Phosphorus cycle: no significant gas phase',[['R',0,2,10,5.5,'rock, sediment',4],['S',14,6,26,9.5,'soil: phosphate',2],['P',30,6,40,9.5,'producers',2],['C',30,0,40,3.5,'consumers',2],['W',14,0,26,3.5,'water: phosphate',0]],[[6,5.7,13.8,7.4,2],[26.2,8.6,29.8,8.6,2],[29.8,7,26.2,7,1],[35,5.8,35,3.7,2],[20,5.9,20,3.7,0],[13.8,1.5,10.2,2.8,0]],[[5,9,'weathering'],[28,10.6,'uptake'],[28,5.4,'decay'],[38.6,4.8,'eaten'],[16.8,4.8,'runoff'],[8,0.2,'sedimentation']],[-2,43,-1,12]);
const WATER=net('Water cycle: the Sun powers the flows',[['A',8,9,34,12.5,'atmosphere: vapor condenses to clouds',0],['O',0,0,12,4,'ocean',0],['L',16,0,30,4,'land, plants',2],['G',16,-6,30,-2.5,'groundwater',3],['I',34,0,44,4,'snow and ice',4]],[[2,4.2,8.5,8.8,0],[18,8.8,18,4.2,0],[26,4.2,26,8.8,2],[16,2,12.2,2,1],[23,-0.2,23,-2.3,3],[34,2,30.2,2,4]],[[-1,7,'evaporation'],[14.2,6.6,'precipitation'],[31.5,6.6,'transpiration'],[14,3.4,'runoff'],[27.5,-1.3,'infiltration'],[32,3.4,'melt']],[-3,46,-7,14]);
const WEB=net('Fictional food web: arrows point to the eater',[['G',13,0,23,2.6,'grass',2],['H',0,5,10,7.6,'grasshopper',0],['B',27,5,37,7.6,'rabbit',0],['F',0,10,9,12.6,'frog',1],['S',12,10,21,12.6,'snake',1],['X',30,10,38,12.6,'fox',3],['K',13,15.2,23,17.8,'hawk',3]],[[18,2.8,5,4.8,2],[18,2.8,32,4.8,2],[4.5,7.8,4.5,9.8,0],[9.2,11.3,11.8,11.3,1],[16.5,12.8,17.5,15,1],[34,7.8,34,9.8,0],[28,7.8,22.5,15,0]],[[18,-1.5,'decomposers feed on dead matter from every level',1]],[-2,40,-3,19.5]);
const TRY=[
 'Try it: a fictional watershed receives 90 cm of precipitation in a year and loses 60 cm to evapotranspiration, with no change in stored water. How many centimeters become runoff?',
 'Try it: a fictional grassland has a gross primary productivity of 1,800 kcal per square meter per year, and its producers use 600 kcal of that in respiration. What is the net primary productivity in kcal per square meter per year?',
 'Try it: a fictional pond’s producers capture 50,000 kcal. Using the 10% rule, how many kcal reach the secondary consumers?',
 'Try it: in a fictional web the arrows are plankton → shrimp, plankton → krill, shrimp → squid, krill → squid, krill → penguin and squid → penguin. How many different food chains lead from plankton to penguin? Give the number.'
];
